sys_script_include.script:
var Cisco_Secure_Access_Private_Resource_Groups = Class.create();
Cisco_Secure_Access_Private_Resource_Groups.prototype = {
	initialize: function () {
	},

	fetchAndInsertPrivateResourceGroups: function () {
		try {
			gs.info("[CSA - PRG] === Script Started ===");

			// 1. Fetch existing ServiceNow table records into a map keyed by name
			var snowRecords = {};
			var grSnow = new GlideRecord("u_cisco_secure_access_private_resources_group");
			grSnow.query();
			while (grSnow.next()) {
				var name = grSnow.getValue("u_name");
				if (name) {
					snowRecords[name] = {
						sys_id: grSnow.getUniqueValue(),
						description: grSnow.getValue("u_description"),
						resource_ids: grSnow.getValue("u_resource_ids"),
						created_by: grSnow.getValue("u_created_by"),
						modified_by: grSnow.getValue("u_modified_by"),
						created_at: grSnow.getValue("u_created_at"),
						modified_at: grSnow.getValue("u_modified_at"),
						resource_group_id: grSnow.getValue("u_resource_group_id")
					};
				}
			}
			gs.info("[CSA - PRG] ServiceNow records fetched. Count=" + Object.keys(snowRecords).length);

			// 2. Fetch all CSA resource groups
			var token = new GetCSATokenAndRefreshToken().getAuthToken();
			var r = new sn_ws.RESTMessageV2("Cisco Secure Access Private Res Groups", "GET Private Resource Groups");
			r.setRequestHeader("Authorization", "Bearer " + token);
			r.setRequestHeader("Accept", "application/json");
			var response = r.execute();
			var status = response.getStatusCode();
			var body = response.getBody();

			if (status !== 200) {
				gs.error("[CSA - PRG] CSA API Error: " + status + " - " + body);
				return;
			}

			var parsed = JSON.parse(body);
			var csaItems = parsed.items || [];
			gs.info("[CSA - PRG] CSA records fetched. Count=" + csaItems.length);

			// 3. Update ServiceNow rows that match CSA by name
			var updatedCount = 0;
			for (var i = 0; i < csaItems.length; i++) {
				var item = csaItems[i];
				var name = item.name;

				if (snowRecords[name]) {
					var existing = snowRecords[name];
					var grUpdate = new GlideRecord("u_cisco_secure_access_private_resources_group");
					if (grUpdate.get(existing.sys_id)) {
						var needUpdate = false;

						if (!existing.description && item.description) { grUpdate.setValue("u_description", item.description); needUpdate = true; }
						if (!existing.resource_ids && item.resourceIds) { grUpdate.setValue("resource_ids", item.resourceIds.join(",")); needUpdate = true; }
						if (!existing.created_by && item.createdBy) { grUpdate.setValue("created_by", item.createdBy); needUpdate = true; }
						if (!existing.modified_by && item.modifiedBy) { grUpdate.setValue("modified_by", item.modifiedBy); needUpdate = true; }
						if (!existing.created_at && item.createdAt) { grUpdate.setValue("created_at", item.createdAt); needUpdate = true; }
						if (!existing.modified_at && item.modifiedAt) { grUpdate.setValue("modified_at", item.modifiedAt); needUpdate = true; }
						if (!existing.resource_group_id && item.resourceGroupId) { grUpdate.setValue("resource_group_id", item.resourceGroupId); needUpdate = true; }

						if (needUpdate) {
							grUpdate.update();
							updatedCount++;
							gs.info("[CSA - PRG] Updated SNOW record by name: " + name + " (RG ID: " + item.resourceGroupId + ")");
						} else {
							gs.info("[CSA - PRG] No missing fields for: " + name);
						}
					}
				} else {
					gs.info("[CSA - PRG] CSA resource group '" + name + "' not found in SNOW table → skipped");
				}
			}

			gs.info("[CSA - PRG] Completed. Records updated=" + updatedCount);

		} catch (e) {
			gs.error("[CSA - PRG] Script Error: " + e.message);
		}
	},

	type: 'Cisco_Secure_Access_Private_Resource_Groups'
};
